import "./ProblemTable.css";

export interface ProblemRow {
  title: string;
  pattern: string;
  minutes: number;
  review: string;
  due: boolean;
}

export interface ProblemTableProps {
  rows: readonly ProblemRow[];
}

export function ProblemTable({ rows }: ProblemTableProps) {
  return (
    <div
      className="problem-table-scroll"
      role="region"
      aria-label="Solved problems"
      tabIndex={0}
    >
      <table className="problem-table">
        <caption className="sr-only">Solved problems and next review</caption>
        <thead>
          <tr>
            <th scope="col">Title</th>
            <th scope="col">Pattern</th>
            <th scope="col" className="is-num">Minutes</th>
            <th scope="col">Next review</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={4} className="is-empty">No solved problems yet.</td>
            </tr>
          ) : (
            rows.map((row, index) => (
              <tr key={`${index}-${row.title}`}>
                <td>{row.title}</td>
                <td>{row.pattern}</td>
                <td className="is-num">{row.minutes}</td>
                <td className={row.due ? "is-due" : undefined}>
                  {row.review}
                  {row.due && <span className="sr-only"> (due today)</span>}
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}
```

```css
