  color: var(--muted);
  font-weight: 600;
}

.problem-table tbody tr:hover {
  background: var(--myelin-wash);
}

.problem-table .is-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.problem-table td.is-due {
  background: var(--cresyl-wash);
  color: var(--ink);
  font-weight: 600;
  box-shadow: inset 3px 0 0 var(--cresyl);
}

.problem-table .is-empty {
  color: var(--muted);
  text-align: center;
}
